    'export function uniqueById(values) { return [...new Map(values.map((value) => [value.id, value])).values()]; }',
    'export function uniqueById(values) { const order = []; const byId = new Map(); for (const value of values) { if (!value || !Object.hasOwn(value, "id") || typeof value.id !== "string") throw new Error("invalid_id"); if (!byId.has(value.id)) order.push(value.id); byId.set(value.id, value); } return order.map((id) => byId.get(id)); }',
    'assert.deepEqual(uniqueById([{ id: "b", n: 1 }, { id: "a", n: 2 }, { id: "b", n: 3 }]), [{ id: "b", n: 3 }, { id: "a", n: 2 }]);',
