    'export function toSlug(value) { return String(value).normalize("NFKD").replace(/[\\u0300-\\u036f]/g, "").replace(/[A-Z]/g, (character) => character.toLowerCase()).replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, ""); }',
    'assert.equal(toSlug("  Café au lait  "), "cafe-au-lait");',
