    'export function parseInteger(value) { if (typeof value !== "string" || !/^(0|-?[1-9]\\d*)$/.test(value)) throw new Error("invalid_integer"); const number = Number(value); if (!Number.isSafeInteger(number)) throw new Error("invalid_integer"); return number; }',
