    'export function deepFreeze(value) { return Object.freeze(value); }',
    'export function deepFreeze(value, seen = new Set()) { if (!value || typeof value !== "object" || seen.has(value)) return value; seen.add(value); const plain = Array.isArray(value) || Object.getPrototypeOf(value) === Object.prototype || Object.getPrototypeOf(value) === null; if (plain) for (const item of Object.values(value)) deepFreeze(item, seen); return Object.freeze(value); }',
