    'assert.equal(decodeBase64Url("aGVsbG8"), "hello");',
    'assert.throws(() => decodeBase64Url("a="), /invalid_base64url/); assert.throws(() => decodeBase64Url("A"), /invalid_base64url/); assert.throws(() => decodeBase64Url("_w"), /invalid_base64url/);',
