    'export function matchesMediaType(actual, expected) { return String(actual).includes(String(expected)); }',
    'const base = (value) => String(value).split(";", 1)[0].trim().toLowerCase(); export function matchesMediaType(actual, expected) { const value = base(actual); const pattern = base(expected); if (!/^[a-z0-9!#$&^_.+-]+\\/(?:[a-z0-9!#$&^_.+-]+|\\*)$/.test(pattern) || !/^[a-z0-9!#$&^_.+-]+\\/[a-z0-9!#$&^_.+-]+$/.test(value)) throw new Error("invalid_media_type"); return pattern.endsWith("/*") ? value.startsWith(`${pattern.slice(0, -1)}`) : value === pattern; }',
