    "retryAfterDelay", "Retry-After delay in milliseconds: canonical nonnegative integer seconds or an HTTP date relative to supplied now, clamped at zero, otherwise invalid_retry_after",
    'export function retryAfterDelay(value, now) { return Number(value) * 1000; }',
    'export function retryAfterDelay(value, now) { if (!Number.isFinite(now)) throw new Error("invalid_retry_after"); if (typeof value === "string" && /^(0|[1-9]\\d*)$/.test(value)) return Number(value) * 1000; if (typeof value !== "string" || !/^(Mon|Tue|Wed|Thu|Fri|Sat|Sun), \\d{2} [A-Z][a-z]{2} \\d{4} \\d{2}:\\d{2}:\\d{2} GMT$/.test(value)) throw new Error("invalid_retry_after"); const timestamp = Date.parse(value); if (!Number.isFinite(timestamp) || new Date(timestamp).toUTCString() !== value) throw new Error("invalid_retry_after"); return Math.max(0, timestamp - now); }',
