export const BENCHMARK_V2_HOLDOUT_MEDIUM_KERNELS = Object.freeze({
  "public-export-registry": kernel("exportName", "return the own string export name and reject inherited or non-string names with invalid_export", 'export function exportName(value) { return value.name; }', 'export function exportName(value) { if (!value || !Object.hasOwn(value, "name") || typeof value.name !== "string") throw new Error("invalid_export"); return value.name; }', 'assert.equal(exportName({ name: "run" }), "run");', 'assert.throws(() => exportName(Object.create({ name: "run" })), /invalid_export/);'),
  "config-default-propagation": kernel("configValue", "preserve explicit false, zero, and empty string while applying the default only to null or undefined", 'export function configValue(value, fallback) { return value || fallback; }', 'export function configValue(value, fallback) { return value ?? fallback; }', 'assert.equal(configValue(false, true), false);', 'assert.equal(configValue(0, 4), 0); assert.equal(configValue(null, 4), 4);'),
  "environment-schema-chain": kernel("readEnvironment", "read an own environment key, return the fallback when absent, and reject non-string present values", 'export function readEnvironment(env, key, fallback) { return env[key] || fallback; }', 'export function readEnvironment(env, key, fallback) { if (!Object.hasOwn(env, key)) return fallback; if (typeof env[key] !== "string") throw new Error("invalid_environment"); return env[key]; }', 'assert.equal(readEnvironment({ MODE: "test" }, "MODE", "prod"), "test");', 'assert.equal(readEnvironment({ MODE: "" }, "MODE", "prod"), ""); assert.throws(() => readEnvironment({ MODE: 1 }, "MODE", "prod"), /invalid_environment/);'),
  "feature-flag-callpath": kernel("isFeatureEnabled", "resolve an own boolean feature override before a boolean default and reject every non-boolean value", 'export function isFeatureEnabled(config, defaults) { return config.enabled || defaults.enabled; }', 'export function isFeatureEnabled(config, defaults) { const value = Object.hasOwn(config, "enabled") ? config.enabled : defaults.enabled; if (typeof value !== "boolean") throw new Error("invalid_feature"); return value; }', 'assert.equal(isFeatureEnabled({ enabled: false }, { enabled: true }), false);', 'assert.throws(() => isFeatureEnabled({ enabled: "false" }, { enabled: true }), /invalid_feature/);'),
  "error-code-surface": kernel("errorCode", "preserve a nonempty own string error code and otherwise return UNKNOWN without consulting inherited properties", 'export function errorCode(error) { return error.code || "UNKNOWN"; }', 'export function errorCode(error) { return error && Object.hasOwn(error, "code") && typeof error.code === "string" && error.code.length > 0 ? error.code : "UNKNOWN"; }', 'assert.equal(errorCode({ code: "E_DOWN" }), "E_DOWN");', 'assert.equal(errorCode(Object.create({ code: "E_BAD" })), "UNKNOWN"); assert.equal(errorCode({ code: "" }), "UNKNOWN");'),
  "version-compatibility-table": kernel("supportsVersion", "accept an integer version only when it is an own key mapped to true in the compatibility table", 'export function supportsVersion(table, version) { return Boolean(table[version]); }', 'export function supportsVersion(table, version) { return Number.isInteger(version) && Object.hasOwn(table, String(version)) && table[String(version)] === true; }', 'assert.equal(supportsVersion({ 1: true, 2: false }, 1), true);', 'assert.equal(supportsVersion({}, "toString"), false); assert.equal(supportsVersion({ 1: 1 }, 1), false);'),
  "event-name-registry": kernel("eventHandler", "return an own function handler for the exact event name and reject missing, inherited, or non-function entries", 'export function eventHandler(registry, name) { return registry[name]; }', 'export function eventHandler(registry, name) { if (!Object.hasOwn(registry, name) || typeof registry[name] !== "function") throw new Error("unknown_event"); return registry[name]; }', 'const fn = () => 1; assert.equal(eventHandler({ ready: fn }, "ready"), fn);', 'assert.throws(() => eventHandler({}, "toString"), /unknown_event/);'),
  "serializer-field-schema": kernel("serializeFields", "copy only schema-listed own fields in schema order, preserving false and null and rejecting a non-array schema", 'export function serializeFields(value, fields) { return Object.fromEntries(fields.map((field) => [field, value[field]]).filter(([, item]) => item)); }', 'export function serializeFields(value, fields) { if (!Array.isArray(fields)) throw new Error("invalid_schema"); const result = {}; for (const field of fields) if (Object.hasOwn(value, field)) result[field] = value[field]; return result; }', 'assert.deepEqual(serializeFields({ a: 0, b: false }, ["b", "a"]), { b: false, a: 0 });', 'assert.deepEqual(serializeFields(Object.create({ x: 1 }), ["x"]), {});'),
  "command-option-contract": kernel("commandCount", "parse an own count option as a canonical nonnegative safe-integer string or use default 1 when absent", 'export function commandCount(options) { return Number(options.count || 1); }', 'export function commandCount(options) { if (!Object.hasOwn(options, "count")) return 1; if (typeof options.count !== "string" || !/^(0|[1-9]\\d*)$/.test(options.count)) throw new Error("invalid_count"); const count = Number(options.count); if (!Number.isSafeInteger(count)) throw new Error("invalid_count"); return count; }', 'assert.equal(commandCount({ count: "0" }), 0);', 'assert.equal(commandCount({}), 1); assert.throws(() => commandCount({ count: "01" }), /invalid_count/); assert.throws(() => commandCount({ count: "9007199254740992" }), /invalid_count/);'),
  "cache-policy-propagation": kernel("cacheTtl", "select an explicit finite nonnegative ttl including zero before the default and reject invalid selected ttl values", 'export function cacheTtl(policy, defaults) { return policy.ttl || defaults.ttl; }', 'export function cacheTtl(policy, defaults) { const value = Object.hasOwn(policy, "ttl") ? policy.ttl : defaults.ttl; if (!Number.isFinite(value) || value < 0) throw new Error("invalid_ttl"); return value; }', 'assert.equal(cacheTtl({ ttl: 0 }, { ttl: 60 }), 0);', 'assert.throws(() => cacheTtl({ ttl: -1 }, { ttl: 60 }), /invalid_ttl/);'),
  "worker-message-registry": kernel("workerMessage", "construct a structured-clone-safe message from an own string type and cloned payload", 'export function workerMessage(value) { return { ...value, payload: value.payload }; }', 'export function workerMessage(value) { if (!value || !Object.hasOwn(value, "type") || typeof value.type !== "string") throw new Error("invalid_message"); return { type: value.type, payload: structuredClone(value.payload) }; }', 'assert.deepEqual(workerMessage({ type: "run", payload: { n: 1 } }), { type: "run", payload: { n: 1 } });', 'const source = { type: "run", payload: { n: 1 }, fn() {} }; const result = workerMessage(source); source.payload.n = 2; assert.equal(result.payload.n, 1); assert.doesNotThrow(() => structuredClone(result));'),
  "route-table-contract": kernel("routeHandler", "match exact own method, pathname, and function handler fields without prefix matching or inherited handlers", 'export function routeHandler(routes, method, pathname) { return routes.find((route) => pathname.startsWith(route.path)).handler; }', 'export function routeHandler(routes, method, pathname) { const route = routes.find((entry) => entry && Object.hasOwn(entry, "method") && Object.hasOwn(entry, "path") && Object.hasOwn(entry, "handler") && entry.method === method && entry.path === pathname && typeof entry.handler === "function"); if (!route) throw new Error("route_not_found"); return route.handler; }', 'const handler = () => 1; assert.equal(routeHandler([{ method: "GET", path: "/a", handler }], "GET", "/a"), handler);', 'assert.throws(() => routeHandler([{ method: "GET", path: "/a", handler() {} }], "GET", "/ab"), /route_not_found/); const inherited = Object.assign(Object.create({ handler() {} }), { method: "GET", path: "/a" }); assert.throws(() => routeHandler([inherited], "GET", "/a"), /route_not_found/);'),
  "retry-policy-propagation": kernel("retryDelay", "return base multiplied by two to the zero-based nonnegative integer attempt, capped at maximum, with invalid policy rejected", 'export function retryDelay(policy, attempt) { return policy.base * attempt; }', 'export function retryDelay(policy, attempt) { if (!Number.isFinite(policy?.base) || policy.base < 0 || !Number.isFinite(policy?.maximum) || policy.maximum < 0 || !Number.isInteger(attempt) || attempt < 0) throw new Error("invalid_retry_policy"); return Math.min(policy.maximum, policy.base * (2 ** attempt)); }', 'assert.equal(retryDelay({ base: 100, maximum: 1000 }, 0), 100);', 'assert.equal(retryDelay({ base: 100, maximum: 250 }, 3), 250); assert.throws(() => retryDelay({ base: -1, maximum: 2 }, 0), /invalid_retry_policy/);'),
  "log-level-registry": kernel("logLevel", "normalize a string level to lowercase and accept only debug, info, warn, or error", 'export function logLevel(value) { return String(value).toLowerCase(); }', 'export function logLevel(value) { if (typeof value !== "string") throw new Error("invalid_log_level"); const level = value.toLowerCase(); if (!["debug", "info", "warn", "error"].includes(level)) throw new Error("invalid_log_level"); return level; }', 'assert.equal(logLevel("WARN"), "warn");', 'assert.throws(() => logLevel("warning"), /invalid_log_level/); assert.throws(() => logLevel(1), /invalid_log_level/);'),
  "plugin-metadata-contract": kernel("pluginMetadata", "return a fresh record containing an own nonempty string id and canonical boolean enabled defaulting to true", 'export function pluginMetadata(value) { return { id: value.id, enabled: value.enabled || true }; }', 'export function pluginMetadata(value) { if (!value || !Object.hasOwn(value, "id") || typeof value.id !== "string" || value.id.length === 0) throw new Error("invalid_plugin"); const enabled = Object.hasOwn(value, "enabled") ? value.enabled : true; if (typeof enabled !== "boolean") throw new Error("invalid_plugin"); return { id: value.id, enabled }; }', 'assert.deepEqual(pluginMetadata({ id: "x", enabled: false }), { id: "x", enabled: false });', 'assert.throws(() => pluginMetadata(Object.create({ id: "x" })), /invalid_plugin/);'),
  "file-extension-registry": kernel("extensionHandler", "case-insensitively match the final extension including dot against own function entries and reject unknown extensions", 'export function extensionHandler(registry, filename) { return registry[filename.split(".").pop()]; }', 'export function extensionHandler(registry, filename) { const match = typeof filename === "string" ? filename.match(/(\\.[^.\\/]+)$/) : null; const extension = match?.[1].toLowerCase(); if (!extension || !Object.hasOwn(registry, extension) || typeof registry[extension] !== "function") throw new Error("unknown_extension"); return registry[extension]; }', 'const fn = () => 1; assert.equal(extensionHandler({ ".json": fn }, "DATA.JSON"), fn);', 'assert.throws(() => extensionHandler({}, ".env"), /unknown_extension/);'),
  "locale-fallback-chain": kernel("resolveLocale", "choose the first exact available locale from requested order, then fallback, otherwise reject; do not prefix-match", 'export function resolveLocale(requested, available, fallback) { return requested.find((value) => available.some((item) => item.startsWith(value))) || fallback; }', 'export function resolveLocale(requested, available, fallback) { if (!Array.isArray(requested) || !Array.isArray(available)) throw new Error("locale_unavailable"); const found = requested.find((value) => available.includes(value)); if (found !== undefined) return found; if (available.includes(fallback)) return fallback; throw new Error("locale_unavailable"); }', 'assert.equal(resolveLocale(["fr", "en"], ["en", "fr"], "en"), "fr");', 'assert.throws(() => resolveLocale(["en"], ["en-US"], "fr"), /locale_unavailable/);'),
  "job-priority-schema": kernel("priorityRank", "map exact low, normal, or high priorities to 0, 1, or 2 using own registry entries only", 'export function priorityRank(value) { return { low: 0, normal: 1, high: 2 }[value] || 1; }', 'export function priorityRank(value) { const ranks = Object.freeze({ low: 0, normal: 1, high: 2 }); if (!Object.hasOwn(ranks, value)) throw new Error("invalid_priority"); return ranks[value]; }', 'assert.equal(priorityRank("low"), 0); assert.equal(priorityRank("high"), 2);', 'assert.throws(() => priorityRank("toString"), /invalid_priority/);'),
  "metric-label-schema": kernel("metricLabels", "return only allowed own string-valued labels and reject any unknown or non-string label", 'export function metricLabels(value, allowed) { return Object.fromEntries(Object.entries(value).filter(([key]) => allowed.includes(key))); }', 'export function metricLabels(value, allowed) { if (!Array.isArray(allowed)) throw new Error("invalid_labels"); const result = {}; for (const [key, item] of Object.entries(value)) { if (!allowed.includes(key) || typeof item !== "string") throw new Error("invalid_labels"); result[key] = item; } return result; }', 'assert.deepEqual(metricLabels({ method: "GET" }, ["method"]), { method: "GET" });', 'assert.throws(() => metricLabels({ extra: "x" }, ["method"]), /invalid_labels/);'),
  "response-code-registry": kernel("responseStatus", "return the own integer HTTP status for an exact response code and reject missing or out-of-range statuses", 'export function responseStatus(registry, code) { return registry[code] || 500; }', 'export function responseStatus(registry, code) { if (!Object.hasOwn(registry, code) || !Number.isInteger(registry[code]) || registry[code] < 100 || registry[code] > 599) throw new Error("unknown_response"); return registry[code]; }', 'assert.equal(responseStatus({ ok: 200 }, "ok"), 200);', 'assert.throws(() => responseStatus({}, "toString"), /unknown_response/); assert.throws(() => responseStatus({ bad: 99 }, "bad"), /unknown_response/);'),
  "date-format-propagation": kernel("formatUtcDate", "format a valid Date as YYYY-MM-DD in UTC and reject invalid or non-Date values", 'export function formatUtcDate(value) { return `${value.getFullYear()}-${value.getMonth() + 1}-${value.getDate()}`; }', 'export function formatUtcDate(value) { if (!(value instanceof Date) || !Number.isFinite(value.getTime())) throw new Error("invalid_date"); return value.toISOString().slice(0, 10); }', 'assert.equal(formatUtcDate(new Date("2024-02-03T23:00:00-02:00")), "2024-02-04");', 'assert.throws(() => formatUtcDate(new Date(NaN)), /invalid_date/);'),
  "endpoint-path-registry": kernel("endpointPath", "join a base pathname and relative endpoint with exactly one slash while rejecting a .. path segment and absolute URLs", 'export function endpointPath(base, endpoint) { return `${base}/${endpoint}`; }', 'export function endpointPath(base, endpoint) { if (typeof base !== "string" || typeof endpoint !== "string" || endpoint.split("/").includes("..") || /^[a-z]+:/i.test(endpoint)) throw new Error("invalid_endpoint"); return `${base.replace(/\\/+$/g, "")}/${endpoint.replace(/^\\/+/g, "")}`; }', 'assert.equal(endpointPath("/api/", "/users"), "/api/users");', 'assert.throws(() => endpointPath("/api", "../admin"), /invalid_endpoint/); assert.equal(endpointPath("/api", "file..json"), "/api/file..json");'),
  "module-feature-manifest": kernel("enabledModules", "return enabled module ids in input order, requiring own nonempty string id and boolean enabled fields", 'export function enabledModules(values) { return values.filter((value) => value.enabled).map((value) => value.id); }', 'export function enabledModules(values) { return values.map((value) => { if (!value || !Object.hasOwn(value, "id") || typeof value.id !== "string" || value.id.length === 0 || !Object.hasOwn(value, "enabled") || typeof value.enabled !== "boolean") throw new Error("invalid_module"); return value; }).filter((value) => value.enabled).map((value) => value.id); }', 'assert.deepEqual(enabledModules([{ id: "a", enabled: false }, { id: "b", enabled: true }]), ["b"]);', 'assert.throws(() => enabledModules([{ id: "a", enabled: "yes" }]), /invalid_module/);'),
  "deprecation-alias-surface": kernel("resolveAlias", "resolve one exact own alias to a nonempty string target, return the input when unaliased, and reject alias cycles", 'export function resolveAlias(aliases, name) { return aliases[name] || name; }', 'export function resolveAlias(aliases, name) { const seen = new Set(); let current = name; while (Object.hasOwn(aliases, current)) { if (seen.has(current) || typeof aliases[current] !== "string" || aliases[current].length === 0) throw new Error("invalid_alias"); seen.add(current); current = aliases[current]; } return current; }', 'assert.equal(resolveAlias({ old: "new" }, "old"), "new");', 'assert.equal(resolveAlias({ a: "b", b: "c" }, "a"), "c"); assert.throws(() => resolveAlias({ a: "b", b: "a" }, "a"), /invalid_alias/);'),
});

export const BENCHMARK_V2_HOLDOUT_HIGH_KERNELS = Object.freeze({
  "role-inheritance-cycle": kernel("roleAllows", "walk the full own role inheritance chain, throw role_cycle on any cycle, and otherwise grant only an exact own permission while denying unknown roles", 'export function roleAllows(roles, role, permission) { return roles[role].permissions.includes(permission) || roleAllows(roles, roles[role].parent, permission); }', 'export function roleAllows(roles, role, permission) { const seen = new Set(); let current = role; let allowed = false; while (current !== null && current !== undefined) { if (seen.has(current)) throw new Error("role_cycle"); seen.add(current); if (!Object.hasOwn(roles, current)) return false; const entry = roles[current]; if (!Array.isArray(entry.permissions)) return false; allowed ||= entry.permissions.includes(permission); current = entry.parent; } return allowed; }', 'assert.equal(roleAllows({ viewer: { permissions: ["read"], parent: null } }, "viewer", "read"), true);', 'assert.equal(roleAllows({}, "admin", "read"), false); assert.throws(() => roleAllows({ a: { permissions: ["read"], parent: "b" }, b: { permissions: [], parent: "a" } }, "a", "read"), /role_cycle/);'),
  "resource-owner-binding": kernel("mayMutate", "allow mutation only when authenticated actor tenant and id exactly match the resource own tenantId and ownerId fields", 'export function mayMutate(actor, resource) { return actor.role === "admin" || actor.id === resource.ownerId; }', 'export function mayMutate(actor, resource) { return Boolean(actor && resource && Object.hasOwn(resource, "tenantId") && Object.hasOwn(resource, "ownerId") && actor.tenantId === resource.tenantId && actor.id === resource.ownerId); }', 'assert.equal(mayMutate({ id: "u", tenantId: "a" }, { ownerId: "u", tenantId: "a" }), true);', 'assert.equal(mayMutate({ id: "u", tenantId: "a", role: "admin" }, { ownerId: "u", tenantId: "b" }), false);'),
  "signed-redirect-origin": kernel("safeRedirect", "accept an absolute HTTPS redirect only when its exact origin is in the allowlist, return its canonical href, and reject every other input with unsafe_redirect", 'export function safeRedirect(value, allowed) { return allowed.some((origin) => value.startsWith(origin)) ? value : "/"; }', 'export function safeRedirect(value, allowed) { try { const url = new URL(value); if (url.protocol !== "https:" || !allowed.includes(url.origin)) throw new Error(); return url.href; } catch { throw new Error("unsafe_redirect"); } }', 'assert.equal(safeRedirect("https://example.test/a", ["https://example.test"]), "https://example.test/a");', 'assert.throws(() => safeRedirect("https://example.test.evil/a", ["https://example.test"]), /unsafe_redirect/); assert.throws(() => safeRedirect("/relative", ["https://example.test"]), /unsafe_redirect/);'),
  "archive-entry-confinement": kernel("archivePath", "normalize a POSIX archive entry beneath root while rejecting absolute paths, backslashes, empty output, and any traversal outside root", 'import path from "node:path"; export function archivePath(root, entry) { return path.join(root, entry); }', 'import path from "node:path"; export function archivePath(root, entry) { if (typeof entry !== "string" || entry.length === 0 || entry.includes("\\\\") || path.posix.isAbsolute(entry)) throw new Error("unsafe_archive_path"); const normalized = path.posix.normalize(entry); if (normalized === "." || normalized === ".." || normalized.startsWith("../")) throw new Error("unsafe_archive_path"); return path.join(root, ...normalized.split("/")); }', 'assert.equal(archivePath("/safe", "a/b.txt").replaceAll("\\\\", "/").endsWith("/a/b.txt"), true);', 'assert.throws(() => archivePath("/safe", "../escape"), /unsafe_archive_path/); assert.throws(() => archivePath("/safe", "a\\\\b"), /unsafe_archive_path/);'),
  "temporary-file-atomic-replace": kernel("atomicReplace", "perform write, file sync, atomic rename, then directory sync in that exact order", 'export function atomicReplace(store, target, value) { store.write(target, value); }', 'export function atomicReplace(store, target, value) { const temporary = `${target}.tmp`; store.write(temporary, value); store.syncFile(temporary); store.rename(temporary, target); store.syncDirectory(target); }', 'const calls = []; atomicReplace({ write: (p) => calls.push(`write:${p}`), syncFile: (p) => calls.push(`sync:${p}`), rename: (a, b) => calls.push(`rename:${a}:${b}`), syncDirectory: (p) => calls.push(`dir:${p}`) }, "state", "x"); assert.deepEqual(calls, ["write:state.tmp", "sync:state.tmp", "rename:state.tmp:state", "dir:state"]);', 'const calls = []; atomicReplace({ write: () => calls.push("w"), syncFile: () => calls.push("f"), rename: () => calls.push("r"), syncDirectory: () => calls.push("d") }, "x", "y"); assert.deepEqual(calls, ["w", "f", "r", "d"]);'),
  "two-phase-checkpoint-recovery": kernel("recoverCheckpoint", "recover only committed checkpoint data; discard prepared-only data and reject unknown phases", 'export function recoverCheckpoint(record) { return record.data; }', 'export function recoverCheckpoint(record) { if (!record || !["prepared", "committed"].includes(record.phase)) throw new Error("invalid_checkpoint"); return record.phase === "committed" ? structuredClone(record.data) : null; }', 'assert.deepEqual(recoverCheckpoint({ phase: "committed", data: { n: 1 } }), { n: 1 });', 'assert.equal(recoverCheckpoint({ phase: "prepared", data: { n: 1 } }), null); assert.throws(() => recoverCheckpoint({ phase: "done" }), /invalid_checkpoint/);'),
  "reverse-compensation-order": kernel("compensate", "await compensation functions in strict reverse order, continue after individual failures, and return failures in execution order", 'export async function compensate(actions) { return Promise.all(actions.map((action) => action())); }', 'export async function compensate(actions) { const failures = []; for (const action of [...actions].reverse()) { try { await action(); } catch (error) { failures.push(error); } } return failures; }', 'const order = []; const failures = await compensate([async () => order.push("a"), async () => order.push("b")]); assert.deepEqual(order, ["b", "a"]); assert.deepEqual(failures, []);', 'const order = []; const failures = await compensate([async () => order.push("a"), async () => { order.push("b"); throw new Error("b"); }]); assert.deepEqual(order, ["b", "a"]); assert.equal(failures.length, 1);'),
  "append-log-checksum": kernel("readLogRecord", "return a cloned log payload only when checksum(payload) exactly matches the stored checksum", 'export function readLogRecord(record) { return record.payload; }', 'export function readLogRecord(record, checksum) { if (!record || typeof checksum !== "function" || checksum(record.payload) !== record.checksum) throw new Error("corrupt_log"); return structuredClone(record.payload); }', 'assert.deepEqual(readLogRecord({ payload: { n: 1 }, checksum: "ok" }, () => "ok"), { n: 1 });', 'assert.throws(() => readLogRecord({ payload: { n: 1 }, checksum: "bad" }, () => "ok"), /corrupt_log/);'),
  "idempotency-payload-conflict": kernel("idempotentResult", "return the stored result only when an existing record has an own payloadHash that exactly matches; otherwise reject conflict or report missing", 'export function idempotentResult(record, hash) { return record?.result; }', 'export function idempotentResult(record, hash) { if (record === undefined) return { status: "missing" }; if (!record || !Object.hasOwn(record, "payloadHash") || record.payloadHash !== hash) throw new Error("idempotency_conflict"); return { status: "replay", result: structuredClone(record.result) }; }', 'assert.deepEqual(idempotentResult(undefined, "h"), { status: "missing" });', 'assert.deepEqual(idempotentResult({ payloadHash: "h", result: 3 }, "h"), { status: "replay", result: 3 }); assert.throws(() => idempotentResult(Object.create({ payloadHash: "h" }), "h"), /idempotency_conflict/);'),
  "lease-fencing-token": kernel("acceptFencingToken", "accept only a safe-integer fencing token strictly greater than the last accepted token", 'export function acceptFencingToken(last, next) { return next >= last; }', 'export function acceptFencingToken(last, next) { if (!Number.isSafeInteger(last) || !Number.isSafeInteger(next) || next <= last) throw new Error("stale_fencing_token"); return next; }', 'assert.equal(acceptFencingToken(4, 5), 5);', 'assert.throws(() => acceptFencingToken(5, 5), /stale_fencing_token/); assert.throws(() => acceptFencingToken(5, 4), /stale_fencing_token/);'),
  "semaphore-cancellation-release": kernel("withPermit", "acquire one permit and release it exactly once after work success or failure", 'export async function withPermit(semaphore, work) { await semaphore.acquire(); const value = await work(); await semaphore.release(); return value; }', 'export async function withPermit(semaphore, work) { await semaphore.acquire(); try { return await work(); } finally { await semaphore.release(); } }', 'const calls = []; assert.equal(await withPermit({ acquire: async () => calls.push("a"), release: async () => calls.push("r") }, async () => 1), 1); assert.deepEqual(calls, ["a", "r"]);', 'const calls = []; await assert.rejects(withPermit({ acquire: async () => calls.push("a"), release: async () => calls.push("r") }, async () => { throw new Error("fail"); }), /fail/); assert.deepEqual(calls, ["a", "r"]);'),
  "subscriber-settlement-cleanup": kernel("waitForEvent", "subscribe once and always unsubscribe the same listener after resolve, reject, or abort", 'export function waitForEvent(source, signal) { return new Promise((resolve) => source.on(resolve)); }', 'export function waitForEvent(source, signal) { return new Promise((resolve, reject) => { const cleanup = () => { source.off(listener); signal?.removeEventListener("abort", abort); }; const listener = (value) => { cleanup(); resolve(value); }; const abort = () => { cleanup(); reject(new Error("aborted")); }; source.on(listener); signal?.addEventListener("abort", abort, { once: true }); }); }', 'let listener; let removed; const source = { on: (fn) => { listener = fn; }, off: (fn) => { removed = fn; } }; const pending = waitForEvent(source); listener(3); assert.equal(await pending, 3); assert.equal(removed, listener);', 'let listener; let removed; const controller = new AbortController(); const pending = waitForEvent({ on: (fn) => { listener = fn; }, off: (fn) => { removed = fn; } }, controller.signal); controller.abort(); await assert.rejects(pending, /aborted/); assert.equal(removed, listener);'),
  "partial-quorum-result": kernel("quorumResult", "return fulfilled values in input order when at least quorum operations fulfill; otherwise throw quorum_unavailable after all settle", 'export async function quorumResult(operations, quorum) { return Promise.all(operations.map((operation) => operation())); }', 'export async function quorumResult(operations, quorum) { if (!Number.isInteger(quorum) || quorum < 1 || quorum > operations.length) throw new Error("invalid_quorum"); const settled = await Promise.allSettled(operations.map((operation) => operation())); const values = settled.filter((entry) => entry.status === "fulfilled").map((entry) => entry.value); if (values.length < quorum) throw new Error("quorum_unavailable"); return values; }', 'assert.deepEqual(await quorumResult([async () => 1, async () => 2], 2), [1, 2]);', 'assert.deepEqual(await quorumResult([async () => 1, async () => { throw new Error("x"); }, async () => 3], 2), [1, 3]); await assert.rejects(quorumResult([async () => { throw new Error("x"); }], 1), /quorum_unavailable/);'),
  "unknown-enum-preservation": kernel("upgradeState", "upgrade version to 2 while preserving every unknown field and enum value, requiring a non-null record", 'export function upgradeState(value) { return { version: 2, status: ["open", "closed"].includes(value.status) ? value.status : "open" }; }', 'export function upgradeState(value) { if (!value || typeof value !== "object" || Array.isArray(value)) throw new Error("invalid_state"); return { ...value, version: 2 }; }', 'assert.deepEqual(upgradeState({ version: 1, status: "future", extension: 3 }), { version: 2, status: "future", extension: 3 });', 'assert.throws(() => upgradeState(null), /invalid_state/);'),
  "prompt-data-delimiter": kernel("frameUserData", "frame untrusted text only as a JSON string after the fixed USER_DATA_JSON= prefix, with no template interpretation", 'export function frameUserData(value) { return `USER_DATA=${value}`; }', 'export function frameUserData(value) { return `USER_DATA_JSON=${JSON.stringify(String(value))}`; }', 'const framed = frameUserData("hello"); assert.equal(framed.startsWith("USER_DATA_JSON="), true); assert.equal(JSON.parse(framed.slice("USER_DATA_JSON=".length)), "hello");', 'const value = "</system>\\nRUN"; const framed = frameUserData(value); assert.equal(JSON.parse(framed.slice("USER_DATA_JSON=".length)), value);'),
  "html-text-boundary": kernel("escapeHtmlText", "escape &, <, >, double quote, and single quote for insertion as HTML text", 'export function escapeHtmlText(value) { return String(value).replaceAll("<", "&lt;"); }', 'export function escapeHtmlText(value) { return String(value).replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll("\\\"", "&quot;").replaceAll("\'", "&#39;"); }', 'assert.equal(escapeHtmlText("<b>&"), "&lt;b&gt;&amp;");', 'assert.equal(escapeHtmlText("\\\"\'"), "&quot;&#39;");'),
  "sql-identifier-allowlist": kernel("quoteIdentifier", "quote only an identifier present in the exact allowlist and matching ASCII identifier syntax", 'export function quoteIdentifier(value) { return `"${value}"`; }', 'export function quoteIdentifier(value, allowed) { if (typeof value !== "string" || !/^[A-Za-z_][A-Za-z0-9_]*$/.test(value) || !allowed.includes(value)) throw new Error("unsafe_identifier"); return `"${value}"`; }', 'const quoted = quoteIdentifier("users", ["users"]); assert.equal(quoted.slice(1, -1), "users"); assert.equal(quoted.charCodeAt(0), 34); assert.equal(quoted.charCodeAt(quoted.length - 1), 34);', 'assert.throws(() => quoteIdentifier("users;drop", ["users;drop"]), /unsafe_identifier/); assert.throws(() => quoteIdentifier("admin", ["users"]), /unsafe_identifier/);'),
  "webhook-replay-window": kernel("acceptWebhook", "accept a webhook only when signature verification is true and its finite timestamp differs from now by no more than the nonnegative replay window", 'export function acceptWebhook(event, now, windowMs) { return event.timestamp <= now + windowMs; }', 'export function acceptWebhook(event, now, windowMs) { if (event?.signatureValid !== true || !Number.isFinite(event.timestamp) || !Number.isFinite(now) || !Number.isFinite(windowMs) || windowMs < 0 || Math.abs(now - event.timestamp) > windowMs) throw new Error("webhook_rejected"); return true; }', 'assert.equal(acceptWebhook({ signatureValid: true, timestamp: 900 }, 1000, 100), true);', 'assert.throws(() => acceptWebhook({ signatureValid: false, timestamp: 1000 }, 1000, 100), /webhook_rejected/); assert.throws(() => acceptWebhook({ signatureValid: true, timestamp: 1101 }, 1000, 100), /webhook_rejected/);'),
  "dual-read-key-rotation": kernel("verifyWithRotation", "try the own active key then the distinct own previous key and return which key verified, otherwise reject", 'export function verifyWithRotation(value, keys, verify) { return verify(value, keys.active); }', 'export function verifyWithRotation(value, keys, verify) { if (typeof verify !== "function" || !keys || !Object.hasOwn(keys, "active") || typeof keys.active !== "string") throw new Error("invalid_keys"); if (verify(value, keys.active)) return "active"; if (Object.hasOwn(keys, "previous") && typeof keys.previous === "string" && keys.previous !== keys.active && verify(value, keys.previous)) return "previous"; throw new Error("verification_failed"); }', 'assert.equal(verifyWithRotation("x", { active: "a", previous: "b" }, (v, key) => key === "a"), "active");', 'assert.equal(verifyWithRotation("x", { active: "a", previous: "b" }, (v, key) => key === "b"), "previous"); assert.throws(() => verifyWithRotation("x", Object.create({ active: "a" }), () => true), /invalid_keys/);'),
  "pagination-cursor-signature": kernel("decodeCursor", "decode canonical unpadded base64url UTF-8 JSON only after verifier accepts the exact encoded cursor and require an own nonnegative integer offset", 'export function decodeCursor(value) { return JSON.parse(Buffer.from(value, "base64url").toString()); }', 'export function decodeCursor(value, verify) { if (typeof value !== "string" || !/^[A-Za-z0-9_-]+$/.test(value) || value.length % 4 === 1 || typeof verify !== "function" || verify(value) !== true) throw new Error("invalid_cursor"); try { const bytes = Buffer.from(value, "base64url"); if (bytes.toString("base64url") !== value) throw new Error(); const decoded = JSON.parse(new TextDecoder("utf-8", { fatal: true }).decode(bytes)); if (!decoded || !Object.hasOwn(decoded, "offset") || !Number.isInteger(decoded.offset) || decoded.offset < 0) throw new Error(); return decoded; } catch { throw new Error("invalid_cursor"); } }', 'const value = Buffer.from(JSON.stringify({ offset: 2 })).toString("base64url"); assert.deepEqual(decodeCursor(value, () => true), { offset: 2 });', 'const value = Buffer.from(JSON.stringify({ offset: -1 })).toString("base64url"); assert.throws(() => decodeCursor(value, () => true), /invalid_cursor/); assert.throws(() => decodeCursor("e30=", () => true), /invalid_cursor/);'),
  "optimistic-version-compare": kernel("applyVersioned", "apply a record patch only when expectedVersion exactly equals the own current integer version, forbid a patch version, and increment once", 'export function applyVersioned(state, expectedVersion, patch) { return { ...state, ...patch, version: state.version + 1 }; }', 'export function applyVersioned(state, expectedVersion, patch) { if (!state || !Object.hasOwn(state, "version") || !Number.isInteger(state.version) || state.version !== expectedVersion || !patch || typeof patch !== "object" || Array.isArray(patch) || Object.hasOwn(patch, "version")) throw new Error("version_conflict"); return { ...state, ...patch, version: state.version + 1 }; }', 'assert.deepEqual(applyVersioned({ id: 1, version: 2 }, 2, { name: "x" }), { id: 1, version: 3, name: "x" });', 'assert.throws(() => applyVersioned({ version: 2 }, 1, {}), /version_conflict/); assert.throws(() => applyVersioned({ version: 2 }, 2, null), /version_conflict/);'),
  "singleflight-failure-recovery": kernel("singleFlight", "share one pending promise per key, remove it after success or failure, and permit a later retry", 'export async function singleFlight(pending, key, work) { const run = work(); pending.set(key, run); return run; }', 'export function singleFlight(pending, key, work) { if (pending.has(key)) return pending.get(key); const run = Promise.resolve().then(work).finally(() => pending.delete(key)); pending.set(key, run); return run; }', 'const pending = new Map(); let calls = 0; const work = async () => ++calls; assert.deepEqual(await Promise.all([singleFlight(pending, "x", work), singleFlight(pending, "x", work)]), [1, 1]);', 'const pending = new Map(); let calls = 0; await assert.rejects(singleFlight(pending, "x", async () => { calls += 1; throw new Error("fail"); }), /fail/); assert.equal(await singleFlight(pending, "x", async () => ++calls), 2);'),
  "nested-secret-redaction": kernel("redactSecrets", "cycle-safe clone arrays and plain objects while replacing values of case-insensitive password, token, secret, and apiKey keys with [REDACTED]", 'export function redactSecrets(value) { return { ...value, token: "[REDACTED]" }; }', 'export function redactSecrets(value, seen = new Map()) { if (!value || typeof value !== "object") return value; if (seen.has(value)) return seen.get(value); const output = Array.isArray(value) ? [] : {}; seen.set(value, output); for (const [key, item] of Object.entries(value)) output[key] = /^(password|token|secret|apikey)$/i.test(key) ? "[REDACTED]" : redactSecrets(item, seen); return output; }', 'assert.deepEqual(redactSecrets({ nested: { apiKey: "x", ok: 1 } }), { nested: { apiKey: "[REDACTED]", ok: 1 } });', 'const value = { password: "x" }; value.self = value; const result = redactSecrets(value); assert.equal(result.password, "[REDACTED]"); assert.equal(result.self, result);'),
  "exact-capability-match": kernel("hasCapability", "grant only an exact own boolean true capability entry for the requested name", 'export function hasCapability(capabilities, requested) { return Object.keys(capabilities).some((value) => requested.startsWith(value)); }', 'export function hasCapability(capabilities, requested) { return typeof requested === "string" && Object.hasOwn(capabilities, requested) && capabilities[requested] === true; }', 'assert.equal(hasCapability({ "files:read": true }, "files:read"), true);', 'assert.equal(hasCapability({ files: true }, "files:read"), false); assert.equal(hasCapability(Object.create({ admin: true }), "admin"), false);'),
});
